const i={render(){const e=document.createElement("div");return e.innerHTML='\n      <div style="max-width:800px;margin:0 auto;padding:40px 24px;font-family:sans-serif;" data-edit-path="div.0">\n        <h2 style="font-size:1.8rem;color:#7B2FBE;margin:0 0 8px;" data-edit-path="div.0/h2.0">Dynamic Positioning — Never Hardcode Y Values</h2>\n        <p style="color:#555;margin:0 0 20px;" data-edit-path="div.0/p.0">The most common mistake is hardcoding pixel positions. If your avatar size changes, everything overlaps. Always compute positions from the element above.</p>\n        <div style="background:#0D0D0D;border-radius:12px;padding:24px;margin-bottom:20px;overflow-x:auto;" data-edit-path="div.0/div.0">\n          <pre style="color:#00D4AA;font-family:monospace;font-size:0.9rem;line-height:1.8;margin:0;" data-edit-path="div.0/div.0/pre.0"># Always compute positions dynamically\nAV_TOP    = 60           # Avatar top edge\nAV_D      = 112          # Avatar diameter\nAV_BOTTOM = AV_TOP + AV_D   # = 172\n\nBADGE_Y      = AV_BOTTOM + 20         # Pill 20px below avatar\nBADGE_BOTTOM = BADGE_Y + badge_height # computed from font metrics\n\nHL_Y  = BADGE_BOTTOM + 44             # Headline 44px below pill\nSUB_Y = HL_Y + headline_height + 52   # Sub-headline 52px after headline\nDIV_Y = SUB_BOTTOM + 55               # Divider 55px below sub-headline</pre>\n        </div>\n        <div style="background:#fff3cd;border-left:4px solid #F5A623;border-radius:8px;padding:16px 20px;" data-edit-path="div.0/div.1">\n          <strong data-edit-path="div.0/div.1/strong.0">⚠️ Rule:</strong> If you hardcode these numbers, one font size change breaks your entire layout. Always chain from AV_BOTTOM.\n        </div>\n      </div>',e}};export{i as slide};
